	if hasIssue(r, IssueSyncStateInvalid) == nil {
		t.Fatalf("expected sync-state-invalid, got %v", issueCodes(r))
	}
	f := findFeature(t, r, "auth")
	if f.Sync == nil || f.Sync.Liveness == nil || *f.Sync.Liveness != "invalid" {
