	if err := os.MkdirAll(sessionLockDir(ws), 0700); err != nil {
		t.Fatal(err)
	}

	r := buildStatus(t, ws, statusOpts(nil, nil))
	presenceBefore := r.Workspace.RuntimePresence
	if err := r.FilterFeature("auth"); err != nil {
		t.Fatal(err)
	}
