	mustCreateRecord(t, featurePath, DirectSessionRecord{Feature: "auth", Name: "renamed-away"})
	r = buildStatus(t, ws, statusOpts(nil, nil))
	if hasIssue(r, IssueDirectRecordOrphanBranch) == nil {
